    16→    console.error('These can be extracted from browser DevTools network requests to xiaohongshu.com');
    17→    process.exit(1);
    18→}
    19→if (!XS_TOKEN || !XS_COMMON_TOKEN) {
    20→    console.error('Warning: XIAOHONGSHU_XS and XIAOHONGSHU_XS_COMMON are not set');
    21→    console.error('The API may not work without these signature tokens');
    22→    console.error('You can extract these from browser DevTools:');
    23→    console.error('1. Open xiaohongshu.com and search for something');
    24→    console.error('2. Open DevTools Network tab');
    25→    console.error('3. Find the search request to edith.xiaohongshu.com/api/sns/web/v1/search/notes');
