    38→const xhsClient = new XiaohongshuClient(COOKIE, XS_TOKEN, XS_COMMON_TOKEN);
    39→// 定义工具
    40→server.setRequestHandler(ListToolsRequestSchema, async () => {
    41→    return {
    42→        tools: [
    43→            {
    44→                name: 'search_notes',
    45→                description: '搜索小红书笔记',
