    62→                        },
    63→                        sort: {
    64→                            type: 'string',
    65→                            description: '排序方式: general(综合), time_descending(最新), popularity_descending(最热)',
    66→                            enum: ['general', 'time_descending', 'popularity_descending'],
    67→                            default: 'general',
    68→                        },
    69→                    },
    70→                    required: ['keyword'],
    71→                },
    72→            },
    73→            {
    74→                name: 'get_note_comments',
