    76→                inputSchema: {
    77→                    type: 'object',
    78→                    properties: {
    79→                        note_id: {
    80→                            type: 'string',
    81→                            description: '笔记ID',
    82→                        },
    83→                        cursor: {
    84→                            type: 'string',
    85→                            description: '游标，用于分页',
    86→                            default: '',
    87→                        },
    88→                    },
    89→                    required: ['note_id'],
    90→                },
    91→            },
    92→            {
    93→                name: 'search_notes_with_comments',
