    95→                inputSchema: {
    96→                    type: 'object',
    97→                    properties: {
    98→                        keyword: {
    99→                            type: 'string',
   100→                            description: '搜索关键词',
   101→                        },
   102→                        page: {
   103→                            type: 'number',
   104→                            description: '页码，默认为1',
   105→                            default: 1,
   106→                        },
   107→                        page_size: {
   108→                            type: 'number',
