#!/usr/bin/env node
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { CallToolRequestSchema, ErrorCode, ListToolsRequestSchema, McpError, } from '@modelcontextprotocol/sdk/types.js';
import { XiaohongshuClient } from './xiaohongshu-client.js';
// 验证环境变量
const COOKIE = process.env.XIAOHONGSHU_COOKIE;
const XS_TOKEN = process.env.XIAOHONGSHU_XS;
const XS_COMMON_TOKEN = process.env.XIAOHONGSHU_XS_COMMON;
if (!COOKIE) {
    console.error('Error: XIAOHONGSHU_COOKIE environment variable is required');
    console.error('Please set it before running this server');
    console.error('Example: XIAOHONGSHU_COOKIE="your_cookie_here" npx xiaohongshu-mcp');
    console.error('');
    console.error('Note: You may also need to set XIAOHONGSHU_XS and XIAOHONGSHU_XS_COMMON');
    console.error('These can be extracted from browser DevTools network requests to xiaohongshu.com');
    process.exit(1);
}
if (!XS_TOKEN || !XS_COMMON_TOKEN) {
    console.error('Warning: XIAOHONGSHU_XS and XIAOHONGSHU_XS_COMMON are not set');
    console.error('The API may not work without these signature tokens');
    console.error('You can extract these from browser DevTools:');
    console.error('1. Open xiaohongshu.com and search for something');
    console.error('2. Open DevTools Network tab');
    console.error('3. Find the search request to edith.xiaohongshu.com/api/sns/web/v1/search/notes');
    console.error('4. Copy the x-s and x-s-common headers');
}
// 创建 MCP 服务器实例
const server = new Server({
    name: 'xiaohongshu-mcp',
    version: '1.1.0',
}, {
    capabilities: {
        tools: {},
    },
});
// 创建小红书客户端
const xhsClient = new XiaohongshuClient(COOKIE, XS_TOKEN, XS_COMMON_TOKEN);
// 定义工具
server.setRequestHandler(ListToolsRequestSchema, async () => {
    return {
        tools: [
            {
                name: 'search_notes',
                description: '搜索小红书笔记',
                inputSchema: {
                    type: 'object',
                    properties: {
                        keyword: {
                            type: 'string',
                            description: '搜索关键词',
                        },
                        page: {
                            type: 'number',
                            description: '页码，默认为1',
                            default: 1,
                        },
                        page_size: {
                            type: 'number',
                            description: '每页数量，默认为20',
                            default: 20,
                        },
                        sort: {
                            type: 'string',
                            description: '排序方式: general(综合), time_descending(最新), popularity_descending(最热)',
                            enum: ['general', 'time_descending', 'popularity_descending'],
                            default: 'general',
                        },
                    },
                    required: ['keyword'],
                },
            },
            {
                name: 'get_note_comments',
                description: '获取笔记评论',
                inputSchema: {
                    type: 'object',
                    properties: {
                        note_id: {
                            type: 'string',
                            description: '笔记ID',
                        },
                        cursor: {
                            type: 'string',
                            description: '游标，用于分页',
                            default: '',
                        },
                    },
                    required: ['note_id'],
                },
            },
            {
                name: 'search_notes_with_comments',
                description: '搜索笔记并获取每个笔记的评论',
                inputSchema: {
                    type: 'object',
                    properties: {
                        keyword: {
                            type: 'string',
                            description: '搜索关键词',
                        },
                        page: {
                            type: 'number',
                            description: '页码，默认为1',
                            default: 1,
                        },
                        page_size: {
                            type: 'number',
                            description: '每页数量，默认为5（因为会获取评论，建议不要太多）',
                            default: 5,
                        },
                        max_comments_per_note: {
                            type: 'number',
                            description: '每个笔记获取的最大评论数，默认10',
                            default: 10,
                        },
                        sort: {
                            type: 'string',
                            description: '排序方式',
                            enum: ['general', 'time_descending', 'popularity_descending'],
                            default: 'general',
                        },
                    },
                    required: ['keyword'],
                },
            },
        ],
    };
});
// 处理工具调用
server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    try {
        switch (name) {
            case 'search_notes': {
                const { keyword, page = 1, page_size = 20, sort = 'general' } = args;
                console.error(`Searching notes for keyword: ${keyword}`);
                const result = await xhsClient.searchNotes(keyword, page, page_size, sort);
                // 格式化结果
                const formattedResult = {
                    total: result.items?.length || 0,
                    has_more: result.has_more,
                    notes: result.items?.map((item) => ({
                        id: item.id,
                        title: item.note_card?.display_title,
                        user: {
                            nickname: item.note_card?.user?.nickname,
                            user_id: item.note_card?.user?.user_id,
                        },
                        interact_info: {
                            liked_count: item.note_card?.interact_info?.liked_count,
                            collected_count: item.note_card?.interact_info?.collected_count,
                            comment_count: item.note_card?.interact_info?.comment_count,
                            shared_count: item.note_card?.interact_info?.shared_count,
                        },
                        type: item.note_card?.type,
                        xsec_token: item.xsec_token,
                    })) || [],
                };
                return {
                    content: [
                        {
                            type: 'text',
                            text: JSON.stringify(formattedResult, null, 2),
                        },
                    ],
                };
            }
            case 'get_note_comments': {
                const { note_id, cursor = '' } = args;
                console.error(`Getting comments for note: ${note_id}`);
                const result = await xhsClient.getNoteComments(note_id, cursor);
                // 格式化评论结果
                const formattedResult = {
                    has_more: result.has_more,
                    cursor: result.cursor,
                    comments: result.comments?.map((comment) => ({
                        id: comment.id,
                        content: comment.content,
                        user: {
                            nickname: comment.user_info?.nickname,
                            user_id: comment.user_info?.user_id,
                        },
                        like_count: comment.like_count,
                        create_time: comment.create_time,
                        sub_comments: comment.sub_comments?.map((sub) => ({
                            id: sub.id,
                            content: sub.content,
                            user: {
                                nickname: sub.user_info?.nickname,
                                user_id: sub.user_info?.user_id,
                            },
                            like_count: sub.like_count,
                            create_time: sub.create_time,
                        })),
                    })) || [],
                };
                return {
                    content: [
                        {
                            type: 'text',
                            text: JSON.stringify(formattedResult, null, 2),
                        },
                    ],
                };
            }
            case 'search_notes_with_comments': {
                const { keyword, page = 1, page_size = 5, max_comments_per_note = 10, sort = 'general' } = args;
                console.error(`Searching notes and comments for keyword: ${keyword}`);
                // 先搜索笔记
                const notesResult = await xhsClient.searchNotes(keyword, page, page_size, sort);
                // 为每个笔记获取评论
                const notesWithComments = [];
                for (const item of notesResult.items || []) {
                    if (item.model_type !== 'note')
                        continue;
                    try {
                        // getNoteComments 内部已经处理了请求间隔
                        const commentsResult = await xhsClient.getNoteComments(item.id, '', item.xsec_token);
                        notesWithComments.push({
                            id: item.id,
                            title: item.note_card?.display_title,
                            user: {
                                nickname: item.note_card?.user?.nickname,
                                user_id: item.note_card?.user?.user_id,
                            },
                            interact_info: {
                                liked_count: item.note_card?.interact_info?.liked_count,
                                collected_count: item.note_card?.interact_info?.collected_count,
                                comment_count: item.note_card?.interact_info?.comment_count,
                                shared_count: item.note_card?.interact_info?.shared_count,
                            },
                            type: item.note_card?.type,
                            comments: commentsResult.comments?.slice(0, max_comments_per_note).map((comment) => ({
                                id: comment.id,
                                content: comment.content,
                                user: {
                                    nickname: comment.user_info?.nickname,
                                    user_id: comment.user_info?.user_id,
                                },
                                like_count: comment.like_count,
                                create_time: comment.create_time,
                            })) || [],
                        });
                    }
                    catch (error) {
                        console.error(`Failed to get comments for note ${item.id}: ${error}`);
                        // 即使获取评论失败，仍然添加笔记信息
                        notesWithComments.push({
                            id: item.id,
                            title: item.note_card?.display_title,
                            user: {
                                nickname: item.note_card?.user?.nickname,
                                user_id: item.note_card?.user?.user_id,
                            },
                            interact_info: {
                                liked_count: item.note_card?.interact_info?.liked_count,
                                collected_count: item.note_card?.interact_info?.collected_count,
                                comment_count: item.note_card?.interact_info?.comment_count,
                                shared_count: item.note_card?.interact_info?.shared_count,
                            },
                            type: item.note_card?.type,
                            comments: [],
                            comments_error: 'Failed to fetch comments',
                        });
                    }
                }
                return {
                    content: [
                        {
                            type: 'text',
                            text: JSON.stringify({
                                total: notesWithComments.length,
                                has_more: notesResult.has_more,
                                notes_with_comments: notesWithComments,
                            }, null, 2),
                        },
                    ],
                };
            }
            default:
                throw new McpError(ErrorCode.MethodNotFound, `Unknown tool: ${name}`);
        }
    }
    catch (error) {
        if (error instanceof McpError) {
            throw error;
        }
        console.error(`Error executing tool ${name}:`, error);
        throw new McpError(ErrorCode.InternalError, `Tool execution failed: ${error}`);
    }
});
// 启动服务器
async function main() {
    const transport = new StdioServerTransport();
    await server.connect(transport);
    console.error('Xiaohongshu MCP server started');
}
main().catch((error) => {
    console.error('Fatal error:', error);
    process.exit(1);
});
//# sourceMappingURL=index.js.map

